from hypothesis import given, strategies as st
import pytest
import types


def flatten_iter(iterable):
    """``flatten_iter()`` yields all the elements from *iterable* while
    collapsing any nested iterables.

    >>> nested = [[1, 2], [[3], [4, 5]]]
    >>> list(flatten_iter(nested))
    [1, 2, 3, 4, 5]
    """
    from collections.abc import Iterable
    for item in iterable:
        if isinstance(item, Iterable) and (not isinstance(item, (str, bytes))):
            yield from flatten_iter(item)
        else:
            yield item


@given(iterable=st.recursive(
    st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans(), st.none()),
    lambda children: st.lists(children, max_size=5),
    max_leaves=20
))
def test_idempotence(iterable):
    assert list(flatten_iter(flatten_iter(iterable))) == list(flatten_iter(iterable))


@given(iterable=st.recursive(
    st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans(), st.none()),
    lambda children: st.lists(children, max_size=5),
    max_leaves=20
))
def test_invariant_preservation(iterable):
    from collections.abc import Iterable as _Iterable

    def count_leaves(obj):
        if isinstance(obj, _Iterable) and not isinstance(obj, (str, bytes)):
            return sum(count_leaves(item) for item in obj)
        else:
            return 1

    expected = count_leaves(iterable)
    actual = sum(1 for _ in flatten_iter(iterable))
    assert actual == expected


@given(
    a=st.recursive(
        st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans(), st.none()),
        lambda children: st.lists(children, max_size=5),
        max_leaves=20
    ),
    b=st.recursive(
        st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans(), st.none()),
        lambda children: st.lists(children, max_size=5),
        max_leaves=20
    )
)
def test_metamorphic(a, b):
    combined = list(flatten_iter([a, b]))
    separate = list(flatten_iter(a)) + list(flatten_iter(b))
    assert combined == separate


@given(iterable=st.recursive(
    st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans(), st.none()),
    lambda children: st.lists(children, max_size=5),
    max_leaves=20
))
def test_type_postcondition(iterable):
    assert isinstance(flatten_iter(iterable), types.GeneratorType)


@given(iterable=st.recursive(
    st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans(), st.none()),
    lambda children: st.lists(children, max_size=5),
    max_leaves=20
))
def test_totality(iterable):
    # Should not raise for any finitely nested iterable of non-iterable leaves
    list(flatten_iter(iterable))

from hypothesis import given, strategies as st
import pytest


def format_invocation(name='', args=(), kwargs=None, **kw):
    """Given a name, positional arguments, and keyword arguments, format
    a basic Python-style function call.

    >>> print(format_invocation('func', args=(1, 2), kwargs={'c': 3}))
    func(1, 2, c=3)
    >>> print(format_invocation('a_func', args=(1,)))
    a_func(1)
    >>> print(format_invocation('kw_func', kwargs=[('a', 1), ('b', 2)]))
    kw_func(a=1, b=2)

    """
    _repr = kw.pop('repr', repr)
    if kw:
        raise TypeError('unexpected keyword args: %r' % ', '.join(kw.keys()))
    kwargs = kwargs or {}
    a_text = ', '.join([_repr(a) for a in args])
    if isinstance(kwargs, dict):
        kwarg_items = [(k, kwargs[k]) for k in sorted(kwargs)]
    else:
        kwarg_items = kwargs
    kw_text = ', '.join([f'{k}={_repr(v)}' for k, v in kwarg_items])
    all_args_text = a_text
    if all_args_text and kw_text:
        all_args_text += ', '
    all_args_text += kw_text
    return f'{name}({all_args_text})'


@given(
    name=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=20),
    args=st.tuples(*[st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()) for _ in range(5)]).flatmap(lambda t: st.just(t[:st.integers(min_value=0, max_value=5).example()])),
    kwargs=st.one_of(st.none(), st.dictionaries(st.text(alphabet='abcdefghijklmnopqrstuvwxyz_', min_size=1, max_size=10), st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none())), st.lists(st.tuples(st.text(alphabet='abcdefghijklmnopqrstuvwxyz_', min_size=1, max_size=10), st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()))))
)
def test_type_postcondition(name, args, kwargs):
    assert isinstance(format_invocation(name, args, kwargs), str)


@given(
    name=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=20),
    args=st.tuples(*[st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()) for _ in range(5)]).flatmap(lambda t: st.just(t[:st.integers(min_value=0, max_value=5).example()])),
    kwargs=st.one_of(st.none(), st.dictionaries(st.text(alphabet='abcdefghijklmnopqrstuvwxyz_', min_size=1, max_size=10), st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none())), st.lists(st.tuples(st.text(alphabet='abcdefghijklmnopqrstuvwxyz_', min_size=1, max_size=10), st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()))))
)
def test_value_postcondition_starts_ends(name, args, kwargs):
    result = format_invocation(name, args, kwargs)
    assert result.startswith(name + '(')
    assert result.endswith(')')


@given(
    args=st.just(()),
    kwargs=st.just({})
)
def test_value_postcondition_empty(args, kwargs):
    assert format_invocation('', args=args, kwargs=kwargs) == '()'


@given(
    name=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=20),
    a=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()),
    b=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none())
)
def test_metamorphic_more_args_longer(name, a, b):
    result_two = format_invocation(name, args=(a, b), kwargs={})
    result_one = format_invocation(name, args=(a,), kwargs={})
    assert len(result_two) >= len(result_one)


@given(
    name=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=20),
    args=st.tuples(*[st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()) for _ in range(5)]).flatmap(lambda t: st.just(t[:st.integers(min_value=0, max_value=5).example()])),
    kwargs=st.one_of(st.none(), st.dictionaries(st.text(alphabet='abcdefghijklmnopqrstuvwxyz_', min_size=1, max_size=10), st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none())), st.lists(st.tuples(st.text(alphabet='abcdefghijklmnopqrstuvwxyz_', min_size=1, max_size=10), st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none()))))
)
def test_totality(name, args, kwargs):
    format_invocation(name, args, kwargs)

from hypothesis import given, strategies as st
import pytest


def under2camel(under_string):
    """Converts an underscored string to camelcased. Useful for turning a
    function name into a class name.

    >>> under2camel('complex_tokenizer')
    'ComplexTokenizer'
    """
    return ''.join((w.capitalize() or '_' for w in under_string.split('_')))


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu'), whitelist_characters='_'), min_size=0))
def test_type_postcondition(under_string):
    assert isinstance(under2camel(under_string), str)


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu'), whitelist_characters='_'), min_size=1).filter(lambda s: len(s) > 0 and not s.startswith('_')))
def test_value_postcondition_first_char_upper(under_string):
    assert under2camel(under_string)[0].isupper()


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu')), min_size=0))
def test_value_postcondition_no_underscore(under_string):
    assert '_' not in under2camel(under_string)


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll',), whitelist_characters='_'), min_size=0))
def test_metamorphic_lower(under_string):
    assert under2camel(under_string.lower()) == under2camel(under_string)


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu'), whitelist_characters='_'), min_size=0))
def test_invariant_preservation_length(under_string):
    assert len(under2camel(under_string).replace('_', '')) == len(under_string.replace('_', ''))


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu'), whitelist_characters='_'), min_size=0))
def test_totality(under_string):
    under2camel(under_string)

from hypothesis import given, strategies as st
import pytest
import math


def floor(x, options=None):
    """Return the floor of *x*. If *options* is set, return the largest
    integer or float from *options* that is less than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> floor(3.5, options=VALID_CABLE_CSA)
    2.5
    >>> floor(2.5, options=VALID_CABLE_CSA)
    2.5

    """
    from math import floor as _floor
    import bisect
    if options is None:
        return _floor(x)
    options = sorted(options)
    i = bisect.bisect_right(options, x)
    if not i:
        raise ValueError('no floor options less than or equal to: %r' % x)
    return options[i - 1]


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_idempotence(x):
    result = floor(x)
    assert floor(result) == result


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_value_postcondition_floor_leq_x(x):
    assert floor(x) <= x


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_value_postcondition_floor_gt_x_minus_1(x):
    result = floor(x)
    assert x - 1 < result <= x


@given(
    x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1)
)
def test_value_postcondition_with_options(x, opts):
    # Filter out NaN values that may sneak in via integers/floats mix
    clean_opts = [v for v in opts if not (isinstance(v, float) and math.isnan(v))]
    # Only run if there is at least one option <= x
    valid = [v for v in clean_opts if v <= x]
    if not valid or not clean_opts:
        return
    result = floor(x, options=clean_opts)
    assert result in clean_opts
    assert result <= x
    assert all(v <= result for v in clean_opts if v <= x)


@given(
    x1=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    x2=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False))
)
def test_metamorphic_monotonicity(x1, x2):
    # Ensure x1 <= x2
    if x1 > x2:
        x1, x2 = x2, x1
    assert floor(x1) <= floor(x2)


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_type_postcondition(x):
    assert isinstance(floor(x), (int, float))

from hypothesis import given, strategies as st
import pytest
import gzip


def gzip_bytes(bytestring, level=6):
    """Turn some bytes into some compressed bytes.

    >>> len(gzip_bytes(b'a' * 10000))
    46

    Args:
        bytestring (bytes): Bytes to be compressed
        level (int): An integer, 1-9, controlling the
          speed/compression. 1 is fastest, least compressed, 9 is
          slowest, but most compressed.

    Note that all levels of gzip are pretty fast these days, though
    it's not really a competitor in compression, at any level.
    """
    from gzip import GzipFile
    from _io import BytesIO as StringIO
    out = StringIO()
    f = GzipFile(fileobj=out, mode='wb', compresslevel=level)
    f.write(bytestring)
    f.close()
    return out.getvalue()


@given(bytestring=st.binary(), level=st.integers(min_value=1, max_value=9))
def test_type_postcondition(bytestring, level):
    assert isinstance(gzip_bytes(bytestring, level), bytes)


@given(bytestring=st.binary(), level=st.integers(min_value=1, max_value=9))
def test_value_postcondition_nonempty(bytestring, level):
    assert len(gzip_bytes(bytestring, level)) > 0


@given(bytestring=st.binary(min_size=10000, max_size=10000).map(lambda _: b'a' * 10000))
def test_value_postcondition_compression(bytestring):
    # For highly repetitive input, compressed output should be much smaller
    assert len(gzip_bytes(bytestring)) << len(bytestring) or len(gzip_bytes(bytestring)) < len(bytestring) // 10


@given(bytestring=st.binary(min_size=1000).filter(lambda b: len(set(b)) < 10))
def test_metamorphic_level(bytestring):
    # For compressible inputs, higher compression level yields <= output size
    assert len(gzip_bytes(bytestring, level=1)) >= len(gzip_bytes(bytestring, level=9))


@given(bytestring=st.binary(), level=st.integers(min_value=1, max_value=9))
def test_totality(bytestring, level):
    # Should not raise for any valid input
    gzip_bytes(bytestring, level)


@given(bytestring=st.binary(), level=st.integers(min_value=1, max_value=9))
def test_round_trip(bytestring, level):
    compressed = gzip_bytes(bytestring, level)
    assert gzip.decompress(compressed) == bytestring

from hypothesis import given, strategies as st
import pytest
import typing


def human_readable_list(items: typing.Sequence[str], delimiter: str=',', conjunction: str='and', *, oxford: bool=True) -> str:
    """
    Given a list of strings, return a human readable string with
    appropriate delimiters and the conjunction word.

    Args:
        items: The list of strings to join.
        delimiter (optional): The delimiter to use between items.
        conjunction (optional): The word to use before the last item.
        oxford (optional): Whether to use the Oxford comma/delimiter before
            the conjunction in lists of 3+ items.

    Returns:
        str: The human readable string.
    """
    if not items:
        return ''
    delimiter = delimiter and delimiter.strip() + ' '
    conjunction = conjunction.strip()
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f'{items[0]} {conjunction} {items[1]}'
    return f'{delimiter.join(items[:-1])}{(delimiter if oxford else ' ')}{conjunction} {items[-1]}'


@given(items=st.lists(st.text(), min_size=0, max_size=10))
def test_type_postcondition(items):
    assert isinstance(human_readable_list(items), str)


@given(items=st.lists(st.text(), min_size=1, max_size=10))
def test_value_postcondition_all_items_present(items):
    result = human_readable_list(items)
    assert all(item in result for item in items)


@given()
def test_value_postcondition_empty_list():
    assert human_readable_list([]) == ''


@given(s=st.text())
def test_value_postcondition_single_item(s):
    assert human_readable_list([s]) == s


@given(items=st.lists(st.text(), min_size=2, max_size=10))
def test_metamorphic_conjunction_present(items):
    result = human_readable_list(items, conjunction='and')
    assert 'and' in result


@given(items=st.lists(st.text(), min_size=3, max_size=10))
def test_metamorphic_oxford_differs(items):
    result_oxford = human_readable_list(items, oxford=True)
    result_no_oxford = human_readable_list(items, oxford=False)
    assert result_oxford != result_no_oxford


@given(
    items=st.lists(st.text(), min_size=0, max_size=10),
    delimiter=st.text(min_size=0, max_size=5),
    conjunction=st.text(min_size=0, max_size=10),
    oxford=st.booleans(),
)
def test_totality(items, delimiter, conjunction, oxford):
    human_readable_list(items, delimiter, conjunction, oxford=oxford)

from hypothesis import given, strategies as st
import pytest


def unwrap_text(text, ending='\n\n'):
    """
    Unwrap text, the natural complement to :func:`textwrap.wrap`.

    >>> text = "Short \\n lines  \\nwrapped\\nsmall.\\n\\nAnother\\nparagraph."
    >>> unwrap_text(text)
    'Short lines wrapped small.\\n\\nAnother paragraph.'

    Args:
       text: A string to unwrap.
       ending (str): The string to join all unwrapped paragraphs
          by. Pass ``None`` to get the list. Defaults to '\\n\\n' for
          compatibility with Markdown and RST.

    """
    all_grafs = []
    cur_graf = []
    for line in text.splitlines():
        line = line.strip()
        if line:
            cur_graf.append(line)
        else:
            all_grafs.append(' '.join(cur_graf))
            cur_graf = []
    if cur_graf:
        all_grafs.append(' '.join(cur_graf))
    if ending is None:
        return all_grafs
    return ending.join(all_grafs)


@given(text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500))
def test_idempotence(text):
    assert unwrap_text(unwrap_text(text)) == unwrap_text(text)


@given(text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500))
def test_metamorphic(text):
    assert unwrap_text(text) == unwrap_text(text.replace('\n', ' \n '))


@given(text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500))
def test_invariant_preservation(text):
    # Count non-empty paragraph blocks in the original text
    original_grafs = [block for block in text.split('\n\n') if any(line.strip() for line in block.splitlines())]
    # Count paragraphs in the unwrapped result (split by '\n\n', filter non-empty)
    result = unwrap_text(text)
    result_grafs = [block for block in result.split('\n\n') if block.strip()]
    assert len(result_grafs) == len(original_grafs)


@given(
    text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500),
    ending=st.one_of(st.none(), st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=20))
)
def test_type_postcondition(text, ending):
    result = unwrap_text(text, ending)
    if ending is None:
        assert isinstance(result, list)
    else:
        assert isinstance(result, str)


@given(
    text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500),
    ending=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=20)
)
def test_value_postcondition(text, ending):
    result = unwrap_text(text, ending)
    # Remove all occurrences of the ending separator, then check no lone newlines remain
    stripped = result.replace(ending, '')
    assert '\n' not in stripped

