from hypothesis import given, strategies as st
import pytest


def to_text(obj, maxlen=None):
    try:
        text = str(obj)
    except Exception:
        try:
            text = str(repr(obj))
        except Exception:
            text = str(object.__repr__(obj))
    if maxlen and len(text) > maxlen:
        text = text[:maxlen - 3] + '...'
    return text


@given(
    obj=st.one_of(st.none(), st.booleans(), st.integers(), st.floats(allow_nan=True, allow_infinity=True), st.text(), st.binary(), st.lists(st.integers()), st.dictionaries(st.text(), st.integers()), st.tuples(st.integers(), st.text())),
    maxlen=st.one_of(st.none(), st.integers(min_value=1, max_value=10000))
)
def test_type_postcondition(obj, maxlen):
    assert isinstance(to_text(obj, maxlen), str)


@given(
    obj=st.one_of(st.none(), st.booleans(), st.integers(), st.floats(allow_nan=True, allow_infinity=True), st.text(), st.binary(), st.lists(st.integers()), st.dictionaries(st.text(), st.integers()), st.tuples(st.integers(), st.text())),
    maxlen=st.integers(min_value=4, max_value=10000)
)
def test_value_postcondition(obj, maxlen):
    # maxlen is not None and maxlen > 3 implies len(to_text(obj, maxlen)) <= maxlen
    assert len(to_text(obj, maxlen)) <= maxlen


@given(
    obj=st.one_of(st.none(), st.booleans(), st.integers(), st.floats(allow_nan=True, allow_infinity=True), st.text(), st.binary(), st.lists(st.integers()), st.dictionaries(st.text(), st.integers()), st.tuples(st.integers(), st.text())),
    maxlen=st.one_of(st.none(), st.integers(min_value=1, max_value=10000))
)
def test_idempotence(obj, maxlen):
    assert to_text(to_text(obj, maxlen), maxlen) == to_text(obj, maxlen)


@given(
    obj=st.one_of(st.none(), st.booleans(), st.integers(), st.floats(allow_nan=True, allow_infinity=True), st.text(), st.binary(), st.lists(st.integers()), st.dictionaries(st.text(), st.integers()), st.tuples(st.integers(), st.text())),
    maxlen=st.one_of(st.none(), st.integers(min_value=1, max_value=10000))
)
def test_totality(obj, maxlen):
    to_text(obj, maxlen)

from hypothesis import given, strategies as st
import pytest


def humanize(word: str) -> str:
    """
    Capitalize the first word and turn underscores into spaces and strip a
    trailing ``"_id"``, if any. Like :func:`titleize`, this is meant for
    creating pretty output.

    Examples::

        >>> humanize("employee_salary")
        'Employee salary'
        >>> humanize("author_id")
        'Author'

    """
    import re
    word = re.sub('_id$', '', word)
    word = word.replace('_', ' ')
    word = re.sub('(?i)([a-z\\d]*)', lambda m: m.group(1).lower(), word)
    word = re.sub('^\\w', lambda m: m.group(0).upper(), word)
    return word


