def test_invariant_preservation(number):
    assert ordinal(number) == ordinal(abs(number))


@given(number=st.integers().filter(lambda n: (abs(int(n)) % 100) not in (11, 12, 13) and ((abs(int(n)) + 1000) % 100) not in (11, 12, 13)))
def test_metamorphic(number):
    assert ordinal(number) == ordinal(number + 1000)


@given(number=st.integers())
def test_totality(number):
    ordinal(number)

