from hypothesis import given, strategies as st
import pytest
import sys


def get_module_callables(mod, ignore=None):
    """Returns two maps of (*types*, *funcs*) from *mod*, optionally
    ignoring based on the :class:`bool` return value of the *ignore*
    callable. *mod* can be a string name of a module in
    :data:`sys.modules` or the module instance itself.
    """
    import sys
    if isinstance(mod, str):
        mod = sys.modules[mod]
    types, funcs = ({}, {})
    for attr_name in dir(mod):
        if ignore and ignore(attr_name):
            continue
        try:
            attr = getattr(mod, attr_name)
        except Exception:
            continue
        try:
            attr_mod_name = attr.__module__
        except AttributeError:
            continue
        if attr_mod_name != mod.__name__:
            continue
        if isinstance(attr, type):
            types[attr_name] = attr
        elif callable(attr):
            funcs[attr_name] = attr
    return (types, funcs)


@given(mod=st.one_of(st.sampled_from(list(sys.modules.keys())), st.sampled_from(list(sys.modules.values()))))
def test_type_postcondition(mod):
    result = get_module_callables(mod)
    assert isinstance(result, tuple)
    assert len(result) == 2
    assert isinstance(result[0], dict)
    assert isinstance(result[1], dict)


@given(mod=st.one_of(st.sampled_from(list(sys.modules.keys())), st.sampled_from(list(sys.modules.values()))))
def test_value_postcondition_types(mod):
    types, funcs = get_module_callables(mod)
    assert all(isinstance(v, type) for v in types.values())


@given(mod=st.one_of(st.sampled_from(list(sys.modules.keys())), st.sampled_from(list(sys.modules.values()))))
def test_value_postcondition_funcs(mod):
    types, funcs = get_module_callables(mod)
    assert all(callable(v) for v in funcs.values())


@given(mod=st.one_of(st.sampled_from(list(sys.modules.keys())), st.sampled_from(list(sys.modules.values()))))
def test_metamorphic(mod):
    types1, funcs1 = get_module_callables(mod)
    all_names = set(types1) | set(funcs1)
    types2, funcs2 = get_module_callables(mod, ignore=lambda name: name not in all_names)
    assert set(types2).issubset(set(types1))
    assert set(funcs2).issubset(set(funcs1))


@given(mod=st.one_of(st.sampled_from(list(sys.modules.keys())), st.sampled_from(list(sys.modules.values()))), ignore=st.one_of(st.none(), st.just(lambda name: False), st.just(lambda name: True), st.builds(lambda chars: (lambda name: any(c in name for c in chars)), st.text(min_size=0, max_size=3))))
def test_totality(mod, ignore):
    get_module_callables(mod, ignore)

