from hypothesis import given, strategies as st
import pytest


def partial_ordering(cls):
    """Class decorator, similar to :func:`functools.total_ordering`,
    except it is used to define `partial orderings`_ (i.e., it is
    possible that *x* is neither greater than, equal to, or less than
    *y*). It assumes the presence of the ``__le__()`` and ``__ge__()``
    method, but nothing else. It will not override any existing
    additional comparison methods.

    .. _partial orderings: https://en.wikipedia.org/wiki/Partially_ordered_set

    >>> @partial_ordering
    ... class MySet(set):
    ...     def __le__(self, other):
    ...         return self.issubset(other)
    ...     def __ge__(self, other):
    ...         return self.issuperset(other)
    ...
    >>> a = MySet([1,2,3])
    >>> b = MySet([1,2])
    >>> c = MySet([1,2,4])
    >>> b < a
    True
    >>> b > a
    False
    >>> b < c
    True
    >>> a < c
    False
    >>> c > a
    False
    """

    def __lt__(self, other):
        return self <= other and (not self >= other)

    def __gt__(self, other):
        return self >= other and (not self <= other)

    def __eq__(self, other):
        return self >= other and self <= other
    if not hasattr(cls, '__lt__'):
        cls.__lt__ = __lt__
    if not hasattr(cls, '__gt__'):
        cls.__gt__ = __gt__
    if not hasattr(cls, '__eq__'):
        cls.__eq__ = __eq__
    return cls


@given(cls=st.sampled_from([
    type('MinimalClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
    }),
    type('SetLikeClass', (set,), {
        '__le__': lambda self, other: set.issubset(self, other),
        '__ge__': lambda self, other: set.issuperset(self, other),
    }),
    type('AlreadyFullClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
        '__lt__': lambda self, other: NotImplemented,
        '__gt__': lambda self, other: NotImplemented,
        '__eq__': lambda self, other: NotImplemented,
    }),
    type('IntWrapperClass', (), {
        '__init__': lambda self, v=0: setattr(self, 'v', v) or None,
        '__le__': lambda self, other: self.v <= other.v,
        '__ge__': lambda self, other: self.v >= other.v,
    }),
    type('AlwaysTrueClass', (), {
        '__le__': lambda self, other: True,
        '__ge__': lambda self, other: True,
    }),
    type('AlwaysFalseClass', (), {
        '__le__': lambda self, other: False,
        '__ge__': lambda self, other: False,
    }),
]))
def test_idempotence(cls):
    # Apply decorator once
    once = partial_ordering(cls)
    lt_after_once = once.__lt__
    gt_after_once = once.__gt__
    eq_after_once = once.__eq__
    # Apply decorator a second time
    twice = partial_ordering(once)
    # The second application must not change any comparison methods
    assert twice.__lt__ is lt_after_once
    assert twice.__gt__ is gt_after_once
    assert twice.__eq__ is eq_after_once


@given(cls=st.sampled_from([
    type('MinimalClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
    }),
    type('SetLikeClass', (set,), {
        '__le__': lambda self, other: set.issubset(self, other),
        '__ge__': lambda self, other: set.issuperset(self, other),
    }),
    type('AlreadyFullClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
        '__lt__': lambda self, other: NotImplemented,
        '__gt__': lambda self, other: NotImplemented,
        '__eq__': lambda self, other: NotImplemented,
    }),
    type('IntWrapperClass', (), {
        '__init__': lambda self, v=0: setattr(self, 'v', v) or None,
        '__le__': lambda self, other: self.v <= other.v,
        '__ge__': lambda self, other: self.v >= other.v,
    }),
    type('AlwaysTrueClass', (), {
        '__le__': lambda self, other: True,
        '__ge__': lambda self, other: True,
    }),
    type('AlwaysFalseClass', (), {
        '__le__': lambda self, other: False,
        '__ge__': lambda self, other: False,
    }),
]))
def test_invariant_preservation(cls):
    # Record pre-existing methods before decoration
    pre_le = cls.__le__
    pre_ge = cls.__ge__
    pre_lt = cls.__dict__.get('__lt__')
    pre_gt = cls.__dict__.get('__gt__')
    pre_eq = cls.__dict__.get('__eq__')

    result = partial_ordering(cls)

    # Identity: the returned object is the same class
    assert result is cls

    # Pre-existing __le__ and __ge__ are unchanged
    assert result.__le__ is pre_le
    assert result.__ge__ is pre_ge

    # Pre-existing __lt__, __gt__, __eq__ (if any) are unchanged
    if pre_lt is not None:
        assert result.__dict__.get('__lt__') is pre_lt
    if pre_gt is not None:
        assert result.__dict__.get('__gt__') is pre_gt
    if pre_eq is not None:
        assert result.__dict__.get('__eq__') is pre_eq


@given(cls=st.sampled_from([
    type('MinimalClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
    }),
    type('SetLikeClass', (set,), {
        '__le__': lambda self, other: set.issubset(self, other),
        '__ge__': lambda self, other: set.issuperset(self, other),
    }),
    type('AlreadyFullClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
        '__lt__': lambda self, other: NotImplemented,
        '__gt__': lambda self, other: NotImplemented,
        '__eq__': lambda self, other: NotImplemented,
    }),
    type('IntWrapperClass', (), {
        '__init__': lambda self, v=0: setattr(self, 'v', v) or None,
        '__le__': lambda self, other: self.v <= other.v,
        '__ge__': lambda self, other: self.v >= other.v,
    }),
    type('AlwaysTrueClass', (), {
        '__le__': lambda self, other: True,
        '__ge__': lambda self, other: True,
    }),
    type('AlwaysFalseClass', (), {
        '__le__': lambda self, other: False,
        '__ge__': lambda self, other: False,
    }),
]))
def test_type_postcondition(cls):
    result = partial_ordering(cls)
    assert isinstance(result, type)


@given(cls=st.sampled_from([
    type('AlreadyFullClass', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
        '__lt__': lambda self, other: NotImplemented,
        '__gt__': lambda self, other: NotImplemented,
        '__eq__': lambda self, other: NotImplemented,
    }),
]))
def test_metamorphic(cls):
    # Capture the pre-existing methods before decoration
    original_lt = cls.__lt__
    original_gt = cls.__gt__
    original_eq = cls.__eq__

    decorated = partial_ordering(cls)

    # Pre-existing methods must not be overridden
    assert decorated.__lt__ is original_lt
    assert decorated.__gt__ is original_gt
    assert decorated.__eq__ is original_eq

from hypothesis import given, strategies as st
import pytest
import math


def frange(stop, start=None, step=1.0):
    """A :func:`range` clone for float-based ranges.

    >>> frange(5)
    [0.0, 1.0, 2.0, 3.0, 4.0]
    >>> frange(6, step=1.25)
    [0.0, 1.25, 2.5, 3.75, 5.0]
    >>> frange(100.5, 101.5, 0.25)
    [100.5, 100.75, 101.0, 101.25]
    >>> frange(5, 0)
    []
    >>> frange(5, 0, step=-1.25)
    [5.0, 3.75, 2.5, 1.25]
    """
    import math
    if not step:
        raise ValueError('step must be non-zero')
    if start is None:
        start, stop = (0.0, stop * 1.0)
    else:
        stop, start = (start * 1.0, stop * 1.0)
    count = int(math.ceil((stop - start) / step))
    ret = [None] * count
    if not ret:
        return ret
    ret[0] = start
    for i in range(1, count):
        ret[i] = ret[i - 1] + step
    return ret


@given(
    stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False),
    start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)),
    step=st.floats(min_value=-1e3, max_value=1e3, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-6)
)
def test_type_postcondition(stop, start, step):
    result = frange(stop, start, step)
    assert isinstance(result, list)
    assert all(isinstance(x, float) for x in result)


@given(
    stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False),
    start=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False),
    step=st.floats(min_value=-1e3, max_value=1e3, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-6)
)
def test_value_postcondition_length(stop, start, step):
    result = frange(stop, start, step)
    expected_len = max(0, math.ceil((stop - start) / step))
    assert len(result) == expected_len


@given(
    stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False),
    start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)),
    step=st.floats(min_value=-1e3, max_value=1e3, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-6)
)
def test_value_postcondition_first_element(stop, start, step):
    result = frange(stop, start, step)
    if result:
        if start is None:
            assert result[0] == pytest.approx(0.0)
        else:
            assert result[0] == pytest.approx(float(start))


@given(
    stop=st.floats(min_value=-1e2, max_value=1e2, allow_nan=False, allow_infinity=False),
    start=st.floats(min_value=-1e2, max_value=1e2, allow_nan=False, allow_infinity=False),
    step=st.floats(min_value=-1e2, max_value=1e2, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-4),
    k=st.floats(min_value=-10.0, max_value=10.0, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-3)
)
def test_metamorphic_scaling(stop, start, step, k):
    result_original = frange(stop, start, step)
    result_scaled = frange(stop * k, start * k, step * k)
    assert len(result_scaled) == len(result_original)


@given(
    stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False),
    start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)),
    step=st.floats(min_value=-1e3, max_value=1e3, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-6)
)
def test_invariant_preservation_step_consistency(stop, start, step):
    result = frange(stop, start, step)
    for i in range(len(result) - 1):
        assert abs((result[i + 1] - result[i]) - step) < 1e-9


@given(
    stop=st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False),
    start=st.one_of(st.none(), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)),
    step=st.floats(min_value=-1e3, max_value=1e3, allow_nan=False, allow_infinity=False).filter(lambda x: abs(x) > 1e-6)
)
def test_totality(stop, start, step):
    # Should not raise for any finite float stop, start, and non-zero step
    frange(stop, start, step)

from hypothesis import given, strategies as st
import pytest


def is_iterable(obj):
    """Similar in nature to :func:`callable`, ``is_iterable`` returns
    ``True`` if an object is `iterable`_, ``False`` if not.

    >>> is_iterable([])
    True
    >>> is_iterable(object())
    False

    .. _iterable: https://docs.python.org/2/glossary.html#term-iterable
    """
    try:
        iter(obj)
    except TypeError:
        return False
    return True


@given(obj=st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.binary(), st.booleans(), st.lists(st.integers()), st.dictionaries(st.text(), st.integers()), st.tuples(st.integers(), st.integers()), st.none(), st.just(object()), st.frozensets(st.integers()), st.iterables(st.integers())))
