from hypothesis import given, strategies as st
import pytest
import math


def ceil(x, options=None):
    """Return the ceiling of *x*. If *options* is set, return the smallest
    integer or float from *options* that is greater than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> ceil(3.5, options=VALID_CABLE_CSA)
    4
    >>> ceil(4, options=VALID_CABLE_CSA)
    4
    """
    from math import ceil as _ceil
    import bisect
    if options is None:
        return _ceil(x)
    options = sorted(options)
    i = bisect.bisect_left(options, x)
    if i == len(options):
        raise ValueError('no ceil options greater than or equal to: %r' % x)
    return options[i]


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_value_postcondition_no_options(x):
    result = ceil(x)
    assert result >= x


@given(
    x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1).map(sorted)
)
def test_value_postcondition_with_options(x, opts):
    # Only test when a valid ceil exists in opts
    if not any(o >= x for o in opts):
        pytest.skip('no option >= x')
    result = ceil(x, options=opts)
    assert result in opts


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_idempotence_no_options(x):
    first = ceil(x)
    assert ceil(first) == first


@given(
    x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1).map(sorted)
)
def test_idempotence_with_options(x, opts):
    if not any(o >= x for o in opts):
        pytest.skip('no option >= x')
    first = ceil(x, options=opts)
    if not any(o >= first for o in opts):
        pytest.skip('no option >= ceil(x, opts)')
    assert ceil(first, options=opts) == first


@given(
    x1=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    x2=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1).map(sorted)
)
def test_metamorphic_monotonicity(x1, x2, opts):
    # Ensure x1 <= x2
    if x1 > x2:
        x1, x2 = x2, x1
    # Both must have a valid ceil in opts
    if not any(o >= x1 for o in opts):
        pytest.skip('no option >= x1')
    if not any(o >= x2 for o in opts):
        pytest.skip('no option >= x2')
    assert ceil(x1, options=opts) <= ceil(x2, options=opts)


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_type_postcondition_no_options(x):
    result = ceil(x)
    assert isinstance(result, int)


@given(
    x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1).map(sorted)
)
def test_type_postcondition_with_options(x, opts):
    if not any(o >= x for o in opts):
        pytest.skip('no option >= x')
    result = ceil(x, options=opts)
    assert isinstance(result, (int, float))

