import pytest
from boltons.strutils import parse_int_list


def format_int_list(int_list, delim=',', range_delim='-', delim_space=False):
    """Returns a sorted range string from a list of positive integers
    (*int_list*). Contiguous ranges of integers are collapsed to min
    and max values. Reverse of :func:`parse_int_list`.

    Args:
        int_list (list): List of positive integers to be converted
           into a range string (e.g. [1,2,4,5,6,8]).
        delim (char): Defaults to ','. Separates integers and
           contiguous ranges of integers.
        range_delim (char): Defaults to '-'. Indicates a contiguous
           range of integers.
        delim_space (bool): Defaults to ``False``. If ``True``, adds a
           space after all *delim* characters.

    >>> format_int_list([1,3,5,6,7,8,10,11,15])
    '1,3,5-8,10-11,15'

    """
    import collections
    output = []
    contig_range = collections.deque()
    for x in sorted(int_list):
        if len(contig_range) < 1:
            contig_range.append(x)
        elif len(contig_range) > 1:
            delta = x - contig_range[-1]
            if delta == 1:
                contig_range.append(x)
            elif delta > 1:
                range_substr = '{:d}{}{:d}'.format(min(contig_range), range_delim, max(contig_range))
                output.append(range_substr)
                contig_range.clear()
                contig_range.append(x)
            else:
                continue
        else:
            delta = x - contig_range[0]
            if delta == 1:
                contig_range.append(x)
            elif delta > 1:
                output.append(f'{contig_range.popleft():d}')
                contig_range.append(x)
            else:
                continue
    else:
        if len(contig_range) == 1:
            output.append(f'{contig_range.popleft():d}')
            contig_range.clear()
        elif len(contig_range) > 1:
            range_substr = '{:d}{}{:d}'.format(min(contig_range), range_delim, max(contig_range))
            output.append(range_substr)
            contig_range.clear()
    if delim_space:
        output_str = (delim + ' ').join(output)
    else:
        output_str = delim.join(output)
    return output_str


@given(int_list=st.lists(st.integers(min_value=1, max_value=10000), max_size=50))
def test_round_trip(int_list):
    assert parse_int_list(format_int_list(int_list)) == sorted(set(int_list))


@given(
    int_list=st.lists(st.integers(min_value=1, max_value=10000), max_size=50),
    delim=st.text(alphabet=st.characters(blacklist_categories=('Nd',), blacklist_characters=('-', ' ')), min_size=1, max_size=1),
    range_delim=st.text(alphabet=st.characters(blacklist_categories=('Nd',), blacklist_characters=(',', ' ')), min_size=1, max_size=1),
    delim_space=st.booleans(),
)
def test_type_postcondition(int_list, delim, range_delim, delim_space):
    assert isinstance(format_int_list(int_list, delim=delim, range_delim=range_delim, delim_space=delim_space), str)


@given(int_list=st.lists(st.integers(min_value=1, max_value=10000), max_size=50))
def test_value_postcondition(int_list):
    # Empty list produces empty string
    assert format_int_list([]) == ''
    # Each integer in int_list appears as a number within format_int_list([x])
    for x in int_list:
        assert str(x) in format_int_list([x])


@given(int_list=st.lists(st.integers(min_value=1, max_value=10000), max_size=50))
def test_metamorphic(int_list):
    result_original = format_int_list(int_list)
    result_sorted = format_int_list(sorted(int_list))
    result_deduped = format_int_list(list(set(int_list)))
    assert result_original == result_sorted
    assert result_original == result_deduped


@given(int_list=st.lists(st.integers(min_value=1, max_value=10000), max_size=50))
def test_invariant_preservation(int_list):
    result = format_int_list(int_list)
    encoded_set = set(parse_int_list(result))
    assert encoded_set == set(int_list)

