        assert all(ord(c) < 128 for c in text)


@given(text=st.text(alphabet=st.characters(max_codepoint=127)))
def test_metamorphic_str_bytes_agree(text):
    if is_ascii(text):
        assert is_ascii(text) == is_ascii(text.encode('ascii'))


@given(text=st.text())
def test_invariant_preservation(text):
    assert is_ascii(text) == is_ascii(text + '')


@given(a=st.text(), b=st.text())
def test_metamorphic_concat(a, b):
