@given(range_string=st.lists(st.integers(min_value=1, max_value=1000), min_size=1, max_size=20).map(lambda lst: ','.join(str(x) for x in sorted(set(lst)))))
def test_type_postcondition(range_string):
    result = parse_int_list(range_string)
    assert isinstance(result, list)
    assert all(isinstance(x, int) for x in result)


@given(range_string=st.lists(st.integers(min_value=1, max_value=1000), min_size=1, max_size=20).map(lambda lst: ','.join(str(x) for x in sorted(set(lst)))))
def test_value_postcondition(range_string):
    result = parse_int_list(range_string)
    assert result == sorted(result)
    assert all(x > 0 for x in result)


