from hypothesis import given, strategies as st
import pytest


def get_all_subclasses(cls):
    """Recursively finds and returns a :class:`list` of all types
    inherited from *cls*.

    >>> class A(object):
    ...     pass
    ...
    >>> class B(A):
    ...     pass
    ...
    >>> class C(B):
    ...     pass
    ...
    >>> class D(A):
    ...     pass
    ...
    >>> [t.__name__ for t in get_all_subclasses(A)]
    ['B', 'D', 'C']
    >>> [t.__name__ for t in get_all_subclasses(B)]
    ['C']

    """
    from collections import deque
    try:
        to_check = deque(cls.__subclasses__())
    except (AttributeError, TypeError):
        raise TypeError('expected type object, not %r' % cls)
    seen, ret = (set(), [])
    while to_check:
        cur = to_check.popleft()
        if cur in seen:
            continue
        ret.append(cur)
        seen.add(cur)
        to_check.extend(cur.__subclasses__())
    return ret


@given(cls=st.from_type(type).filter(lambda t: isinstance(t, type)))
def test_type_postcondition(cls):
    assert isinstance(get_all_subclasses(cls), list)


@given(cls=st.from_type(type).filter(lambda t: isinstance(t, type)))
def test_value_postcondition_elements_are_types(cls):
    assert all(isinstance(t, type) for t in get_all_subclasses(cls))


